import time

def create_counter(initial=0):
    count = initial
    init = initial

    def increment():
        nonlocal count
        count += 1
        return count

    def decrement():
        nonlocal count
        count -= 1
        return count

    def get_count():
        return count

    def reset():
        nonlocal count
        count = init
        return count

    return {
        'increment': increment,
        'decrement': decrement,
        'get_count': get_count,
        'reset': reset
    }

def create_memoize(fn):
    cache = {}

    def memoized(*args):
        key = str(args)
        if key not in cache:
            cache[key] = fn(*args)
        return cache[key]

    return memoized

def create_rate_limiter(max_calls, time_window):
    calls = []

    def limiter():
        now = time.time() * 1000
        nonlocal calls
        calls = [t for t in calls if now - t < time_window]
        if len(calls) >= max_calls:
            return False
        calls.append(now)
        return True

    return limiter

