function createMemoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (!cache.has(key)) {
      cache.set(key, fn(...args));
    }
    return cache.get(key);
  };
}

function createRateLimiter(maxCalls, timeWindow) {
  const calls = [];
  return function() {
    const now = Date.now();
    while (calls.length && now - calls[0] >= timeWindow) {
      calls.shift();
    }
    if (calls.length >= maxCalls) return false;
    calls.push(now);
    return true;
  };
}
